import{_ as t,o as a,c as i,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const h=JSON.parse('{"title":"ADR 0003: Incremental calculation-boundary repair","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/0003-calculation-boundaries.md","filePath":"decisions/0003-calculation-boundaries.md","lastUpdated":1789462242000}'),n={name:"decisions/0003-calculation-boundaries.md"};function s(o,e,l,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="adr-0003-incremental-calculation-boundary-repair" tabindex="-1">ADR 0003: Incremental calculation-boundary repair <a class="header-anchor" href="#adr-0003-incremental-calculation-boundary-repair" aria-label="Permalink to &quot;ADR 0003: Incremental calculation-boundary repair&quot;">​</a></h1><p>Status: implemented on the maintenance branch; structured-data rollout is opt-in. Owner approval: architecture repair and structural inventory-test updates approved. Baseline: <code>e05eb3ba32be613e53832092588e996bb56558fe</code>.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Keep the verified behavior, existing subscriber format and protected engines. Replace responsibilities at their boundaries, rather than pursue a whole-project rewrite. This is a scoped repair, not a claim that every browser panel is now strictly typed.</p><pre class="mermaid">flowchart TD
    UI[Browser input adapter] --&gt; BR[Typed browser search input]
    MCP[MCP input adapter] --&gt; PR[Typed Python search options]
    Core[Protected calculation engines] --&gt; Facts[Calendar facts]
    Facts --&gt; Export[Versioned day-data export]
    Export --&gt; BR
    Facts --&gt; PR
    Rules[Python-owned shared tables] --&gt; Generated[Checked generated browser tables]
    Generated --&gt; BR
    PR --&gt; Service[Transport-independent search service]
    Service --&gt; Raw[Ranked slots with aware instants]
    Raw --&gt; Response[MCP formatting and result limit]
    BR --&gt; Browser[Browser evaluation and typed ranking]
    Browser --&gt; View[Existing result presentation]
</pre><p>The arrows describe responsibility and data flow, not a new shared runtime. The browser and Python implementations remain distinct.</p><h2 id="completed-repair-sequence" tabindex="-1">Completed repair sequence <a class="header-anchor" href="#completed-repair-sequence" aria-label="Permalink to &quot;Completed repair sequence&quot;">​</a></h2><ol><li>Pin shared ranking boundaries with one hand-authored corpus consumed by both runtimes. Preserve MCP signatures and byte-level results with a baseline corpus. Define explicit browser inputs and Python search/result contracts.</li><li>Move multi-day search, night handling, diagnostics and ranking out of MCP formatting. Return all raw candidates with timezone-aware instants; the MCP adapter formats and limits them. Replace mutation of caller-owned score explanation buckets with returned contributions. Move browser ranking into the strictly checked calculation area.</li><li>Export the seven audited manual table/contract groups from their existing Python owners. Validate the generated artifact in the full Python gate. Preserve the browser&#39;s historical Yoga aliases and supported-rule subset.</li><li>Generate <code>.days-v1.json</code> beside the unmodified <code>.ics</code> feeds. Validate version, city, system, timezone and nested field types before using data. Migrate Today and the Muhurta day pipeline to the day-data adapter. Keep the legacy reader as a compatibility fallback during the pilot.</li></ol><h2 id="contracts-intentionally-not-unified" tabindex="-1">Contracts intentionally not unified <a class="header-anchor" href="#contracts-intentionally-not-unified" aria-label="Permalink to &quot;Contracts intentionally not unified&quot;">​</a></h2><ul><li>MCP accepts at most 14 days and presents at most 12 slots.</li><li>Browser search retains its 60-day cap, personal-preference tie-break and chart screening.</li><li>Python has 35 canonical activity profiles; the browser exposes its existing 30-profile subset.</li><li>The browser&#39;s approximate Yoga names retain Priti/Shula/Variyana.</li><li>Night slot tie-breaks retain local-clock ordering, rather than silently switching to UTC order.</li><li>Generated day views retain minute precision and the old relative-date markers.</li><li>ICS summaries/descriptions remain opaque display/legacy strings in the sidecar. Structured facts are projected from engine objects, never reconstructed from those strings.</li><li>Domain source claims and rule semantics are unchanged; engine-pinned fixtures are not independent astronomical verification.</li></ul><h2 id="verification-and-material-change-tests" tabindex="-1">Verification and material change tests <a class="header-anchor" href="#verification-and-material-change-tests" aria-label="Permalink to &quot;Verification and material change tests&quot;">​</a></h2><ul><li><code>tests/test_muhurta_ranking_contract.py</code> and the matching frontend test share independent expected boundaries.</li><li><code>tests/test_muhurta_mcp_compatibility.py</code> pins the original signature and nine complete serialized responses/errors.</li><li><code>tests/test_muhurta_search_boundary.py</code> proves the service returns unformatted, untruncated results without MCP imports.</li><li><code>tests/test_shared_calendar_tables.py</code> rejects generator drift and pins intentional aliases.</li><li>The 48-day structured-data corpus covers three systems, two cities, an eclipse, DST and cross-midnight data.</li><li><code>src/__tests__/calendar-data.test.ts</code> replaces description wording while asserting unchanged structured facts.</li><li><code>tests/test_structured_calendar_browser.py</code> exercises the built Today and Muhurta journeys at mobile and desktop widths.</li><li>Existing behavioral assertions and coverage thresholds remain; only structural/release metadata and loader mocking change.</li><li>Architecture tests compare a committed revision against its own committed inventory ledger, avoiding pre/post-commit count mismatches.</li></ul><h2 id="rollout-and-rollback" tabindex="-1">Rollout and rollback <a class="header-anchor" href="#rollout-and-rollback" aria-label="Permalink to &quot;Rollout and rollback&quot;">​</a></h2><p>The pilot is disabled in ordinary builds until its sidecars have been published. This prevents speculative missing-file requests on existing installations.</p><ol><li>Generate feeds with the existing <code>python -m telugu_panchangam.generate</code> entry point. The existing feed-publication script copies both ICS and day JSON; workflows and CNAME remain untouched.</li><li>Verify sidecars for the supported city/system combinations before enabling the public build.</li><li>Set <code>VITE_STRUCTURED_CALENDAR_ENABLED=true</code> for the browser build to activate the pilot. An explicit <code>false</code> disables it, including local query overrides.</li><li>For local browser inspection only, use <code>?calendarData=structured#today</code> or <code>#tarabalam</code> on loopback.</li><li>Roll back by building with the flag disabled; subscriber feeds and stored profiles are unchanged.</li></ol><p>No public activation, workflow dispatch or feed publication is implied by local verification. Broad replacement of remaining panels, engine unification and API feature parity are outside this repair.</p>`,16)])])}const m=t(n,[["render",s]]);export{h as __pageData,m as default};
